function initials(name){
  return name.replace(/[—.]/g,' ').trim().split(/\s+/).map(w=>w[0]).join('').slice(0,2).toUpperCase();
}

const palette = ['#2B425F','#3E5A78','#5B7A9B','#4F6478','#7C4B4B'];
function officeColor(name){
  let hash = 0;
  for(let i=0;i<name.length;i++) hash = name.charCodeAt(i) + ((hash<<5)-hash);
  return palette[Math.abs(hash) % palette.length];
}

// Ofisin logosu, resmi Instagram hesabından indirilip logos/ klasörüne kaydedildi.
// Instagram hesabı bulunamayan ofisler için site faviconuna geri düşülür.
const NO_LOGO_DOMAINS = new Set(['archdaily.com']);
function officeDomain(website){
  try{ return new URL(website).hostname.replace(/^www\./,''); }
  catch(e){ return null; }
}
function logoUrl(o){
  if(o.logo) return o.logo;
  const domain = officeDomain(o.website);
  if(!domain || NO_LOGO_DOMAINS.has(domain)) return null;
  return `https://icons.duckduckgo.com/ip3/${domain}.ico`;
}

// Ofis dizininde yer almayan ama logosu elde bulunan kurumlar (üniversiteler vb.)
const KNOWN_INSTITUTION_LOGOS = {
  "Yıldız Teknik Üniversitesi": "logos/institutions/ytu-logo.png",
  "MİMARLAB": "logos/site/mimarlab-logo.png",
};
const KNOWN_INSTITUTION_YEARS = {
  "Yıldız Teknik Üniversitesi": 1911,
  "MİMARLAB": 2026,
};

function institutionCell(a){
  if(a.office){
    const o = offices.find(x => x.name === a.office);
    if(o){
      return `
        <div class="institution-cell">
          <a class="institution-item" href="/markalar/${encodeURIComponent(slugify(o.name))}">
            <div class="tag-hole" style="background:${officeColor(o.name)}">${initials(o.name)}${logoUrl(o) ? `<img src="${escapeAttrGlobal(logoUrl(o))}" alt="" loading="lazy" onerror="this.remove()">` : ''}</div>
            <div class="institution-text">
              <span class="institution-name-line">
                <span class="institution-name">${escapeHtmlGlobal(o.name)}${verifiedBadgeHtml('office', o.name, o.badges)}</span>
                ${o.yil ? `<span class="institution-year">${escapeHtmlGlobal(o.yil)}</span>` : ''}
              </span>
              <div class="institution-role">${escapeHtmlGlobal(a.role)}</div>
            </div>
          </a>
        </div>`;
    }
    // Ofis dizininde kayıtlı olmayan kurum (ör. MimarLab, bir üniversite) — link yok
    const knownLogo = KNOWN_INSTITUTION_LOGOS[a.office];
    const knownYear = KNOWN_INSTITUTION_YEARS[a.office];
    return `
      <div class="institution-cell">
        <div class="institution-item">
          <div class="tag-hole" style="background:${knownLogo ? '#fff' : officeColor(a.office)}">${knownLogo ? `<img src="${escapeAttrGlobal(knownLogo)}" alt="" loading="lazy" onerror="this.remove()">` : escapeHtmlGlobal(initials(a.office))}</div>
          <div class="institution-text">
            <span class="institution-name-line">
              <span class="institution-name">${escapeHtmlGlobal(a.office)}</span>
              ${knownYear ? `<span class="institution-year">${escapeHtmlGlobal(knownYear)}</span>` : ''}
            </span>
            <div class="institution-role">${escapeHtmlGlobal(a.role || '')}</div>
          </div>
        </div>
      </div>`;
  }
  if(a.status){
    return `
      <div class="institution-cell institution-cell-status">
        <span class="status-pill">${escapeHtmlGlobal(a.status)}</span>
      </div>`;
  }
  return `<div class="institution-cell"></div>`;
}

// Satın alınıp admin tarafından onaylanmış rozetler /api/public/badges'ten gelir; sayfa ilk
// render edildiğinde henüz hazır olmayabileceğinden 'mimarlab-badges-ready' event'i ile
// dinleyen sayfalar (index/mimar/ofis listeleri) rozetler gelince yeniden render edebilir.
const dynamicBadges = { architect: {}, office: {} };
// Worker'ın esbuild bundle'ında (bkz. dosya sonundaki module.exports notu) bu dosya import
// edildiğinde çalışmaması için korunuyor — tarayıcıda `document` her zaman tanımlı olduğundan
// davranış değişmez.
if (typeof document !== 'undefined') {
fetch('/api/public/badges').then(r => r.ok ? r.json() : null).then(d => {
  if(d){ Object.assign(dynamicBadges.architect, d.architect || {}); Object.assign(dynamicBadges.office, d.office || {}); }
  window.dispatchEvent(new Event('mimarlab-badges-ready'));
}).catch(()=>{});
}

// Üç rozet kademesi: Doğrulanmış Üye kimlik doğrulamasını temsil eder (Instagram'ın mavi
// doğrulanmış profil rozeti gibi); Altın Üye ve Elmas Üye ise daha üst kademe, aylık abonelik
// olarak ödenen üyeliklerdir ve kendi rengiyle ayrı bir rozet olarak gösterilir (bkz.
// hesabim.html#BADGE_TIERS ve src/routes/badges.js#BADGE_PRICES ile aynı isimler/anahtarlar).
// 'destekci' (Destekçi) kasıtlı olarak burada yok: yalnızca destek amaçlıdır, hiçbir görünür
// rozet ya da hak vermez (bkz. src/routes/badges.js#handlePublicBadges, orada da hariç tutulur).
const BADGE_LABELS = { verified:'Doğrulanmış Üye', gold:'Altın Üye', platinum:'Elmas Üye' };
const BADGE_COLORS = { verified:'#0095F6', gold:'#D4A72C', platinum:'#4FB3D9' };

// Native `title` tooltip'i masaüstünde gecikmeli/tutarsız, mobilde ise dokunmayla hiç çalışmıyor;
// bu yüzden kendi tooltip'imizi kuruyoruz. Rozet ikonları çoğu yerde overflow:hidden/auto olan bir
// kartın/satırın içinde yer alır (ör. .person-card, .home-card, .row-name-line) — tooltip o kartın
// İÇİNDE bir çocuk olarak render edilirse üste doğru taştığında ata elemanın overflow'u tarafından
// kırpılıp görünmez kalıyordu. Bunun yerine document.body'ye eklenmiş TEK PAYLAŞILAN bir tooltip
// elemanı kullanılır; document koordinatlarında (position:absolute + scrollX/scrollY) konumlanır ve
// çok yüksek bir z-index taşır, böylece hangi kartın/satırın içinde olursa olsun her zaman sayfanın
// en önünde ve tam görünür kalır. Stil burada bir kere <head>'e enjekte edilir (data.js her sayfada
// yükleniyor); masaüstünde hover, mobilde/tıklamada 'tip-show' class'ı ile gösterilir.
// Worker'ın esbuild bundle'ında document/window global'leri olmadığından bu blok da korunuyor.
if (typeof document !== 'undefined') {
if(!document.getElementById('verified-badge-style')){
  const badgeStyle = document.createElement('style');
  badgeStyle.id = 'verified-badge-style';
  badgeStyle.textContent = `
    .verified-badge-icon{position:relative; cursor:pointer;}
    .verified-badge-tip-floating{
      position:absolute; top:-9999px; left:-9999px;
      background:#1B2A3D; color:#fff; font-family:'Inter', sans-serif; font-size:11px; font-weight:600;
      line-height:1.3; white-space:nowrap; padding:5px 9px; border-radius:6px;
      opacity:0; pointer-events:none; transition:opacity .12s ease; z-index:99999;
    }
    .verified-badge-tip-floating::after{
      content:''; position:absolute; top:100%; left:50%; transform:translateX(-50%);
      border:5px solid transparent; border-top-color:#1B2A3D;
    }
    .verified-badge-tip-floating.show{opacity:1;}
  `;
  document.head.appendChild(badgeStyle);
}
}

let badgeTooltipEl = null;
function ensureBadgeTooltip(){
  if(!badgeTooltipEl){
    badgeTooltipEl = document.createElement('div');
    badgeTooltipEl.className = 'verified-badge-tip-floating';
    document.body.appendChild(badgeTooltipEl);
  }
  return badgeTooltipEl;
}
function showBadgeTooltip(icon){
  const tip = ensureBadgeTooltip();
  tip.textContent = icon.dataset.tip || '';
  const iconRect = icon.getBoundingClientRect();
  const tipRect = tip.getBoundingClientRect();
  const left = iconRect.left + window.scrollX + iconRect.width / 2 - tipRect.width / 2;
  const top = iconRect.top + window.scrollY - tipRect.height - 7;
  tip.style.left = `${Math.max(4, left)}px`;
  tip.style.top = `${top}px`;
  tip.classList.add('show');
}
function hideBadgeTooltip(){
  if(badgeTooltipEl) badgeTooltipEl.classList.remove('show');
}

// Masaüstünde imleç üzerine gelince göster/gizle (delegasyonla — rozet ikonları sayfa boyunca
// tekrar tekrar innerHTML ile render edildiğinden tek tek dinleyici eklemek yerine document
// üzerinden delege edilir).
// `typeof document !== 'undefined'` koruması yalnızca bu dosya Worker'ın esbuild bundle'ına
// import edildiğinde (bkz. dosya sonundaki module.exports notu) devreye giriyor — DOM'suz bu
// ortamda document/window global'leri yok. Tarayıcıda her zaman true olduğundan davranış aynı.
if (typeof document !== 'undefined') {
document.addEventListener('mouseover', (e)=>{
  const icon = e.target.closest('.verified-badge-icon');
  if(icon) showBadgeTooltip(icon);
});
document.addEventListener('mouseout', (e)=>{
  const icon = e.target.closest('.verified-badge-icon');
  if(icon && !icon.contains(e.relatedTarget) && !icon.classList.contains('tip-show')) hideBadgeTooltip();
});
// Rozete dokunma/tıklama: tooltip'i aç/kapat, ve rozet çoğunlukla bir <a> içinde olduğundan
// (ör. mimar/ofis kartı) tıklamanın linki tetikleyip sayfadan çıkmasını engelle.
document.addEventListener('click', (e)=>{
  const badge = e.target.closest('.verified-badge-icon');
  document.querySelectorAll('.verified-badge-icon.tip-show').forEach(b => { if(b !== badge) b.classList.remove('tip-show'); });
  if(badge){
    e.preventDefault();
    e.stopPropagation();
    const wasShown = badge.classList.contains('tip-show');
    badge.classList.toggle('tip-show');
    if(wasShown) hideBadgeTooltip(); else showBadgeTooltip(badge);
  } else {
    hideBadgeTooltip();
  }
});
// Sayfa kaydırılınca (kartın kendisi ya da bir üst konteyner) konumu bayatlamasın diye tooltip
// kapatılır — filtre/sayfa değişimiyle tetiklenen bir yeniden render de rozet elemanını DOM'dan
// kaldırabileceğinden aynı güvenlik burada da işe yarar.
window.addEventListener('scroll', ()=>{
  hideBadgeTooltip();
  document.querySelectorAll('.verified-badge-icon.tip-show').forEach(b => b.classList.remove('tip-show'));
}, { passive:true, capture:true });
}

// profileType: 'architect' | 'office'; profileKey: architects[].name ya da offices[].name;
// staticBadges: data.js kaydındaki opsiyonel badges[] alanı — yalnızca o profil için gerçek
// (satın alınıp onaylanmış) bir rozet YOKSA başlangıç/seed değeri olarak kullanılır. Gerçek rozet
// varsa (dynamicBadges) her zaman önceliklidir, aksi halde bir kullanıcı rozetini yükselttiğinde
// (ör. Altın → Elmas) data.js'teki eski statik değer siteye takılıp kalırdı.
// Bir profilin birden fazla rozeti varsa (ör. Doğrulanmış Mimar + Gold Üye) her biri kendi
// rengi ve üzerine gelince/dokununca kendi adını gösteren ayrı bir ikon olarak yan yana render edilir.
// Doğrulanmış Üye/Altın Üye: sekiz köşeli mühür + onay işareti. Elmas Üye kendi başına, bu
// ikonla karıştırılmasın diye ayrı bir yakut/elmas (gem) ikonu kullanır — bkz. kullanıcı geri
// bildirimi: iki rozet birbirinin aynısı görünüyordu.
const SEAL_BADGE_SVG = '<path d="M12 2 14.5 5.5 19 5l-.5 4.5L22 12l-3.5 2.5.5 4.5-4.5-.5L12 22l-2.5-3.5-4.5.5.5-4.5L2 12l3.5-2.5L5 5l4.5.5Z"/><path d="M9 12.5l2 2 4-4.5" stroke="#fff" stroke-width="1.8" fill="none" stroke-linecap="round" stroke-linejoin="round"/>';
const GEM_BADGE_SVG = '<path d="M4.5 9 8 3.5h8L19.5 9 12 21.5 4.5 9Z"/><path d="M4.5 9h15M8 3.5 12 9m4-5.5L12 9M12 9v12.5" stroke="#fff" stroke-width="1.1" stroke-linecap="round" stroke-linejoin="round" opacity="0.6"/>';
// Tek bir rozet türünü ikon olarak render eder — verifiedBadgeHtml (mimar/marka profili, birden
// fazla rozet) ile yorum/gönderi satırlarındaki KİŞİSEL rozet (tek rozet, bkz. src/routes/
// comments.js#listComments'in döndürdüğü user_badge, src/routes/public.js#toPublicShape'in
// ownerBadge alanı) arasında paylaşılır.
function badgeIconHtml(badgeType, size){
  if(!badgeType) return '';
  size = size || 13;
  const isGem = badgeType === 'platinum';
  // Elmas (platinum) ikonu diğer rozetlere göre daha dar/sivri duruyordu (bkz. kullanıcı isteği:
  // "elmas rozetini biraz sağa ve sola doğru büyüt") — viewBox kare olduğundan yalnızca width'i
  // artırıp preserveAspectRatio="none" ile yatayda esnetiyoruz; height (ve dolayısıyla metinle
  // hizalanan satır yüksekliği) değişmeden kalır.
  const width = isGem ? Math.round(size * 1.3) : size;
  return `<span class="verified-badge-icon" data-tip="${escapeAttrGlobal(BADGE_LABELS[badgeType] || badgeType)}" style="color:${BADGE_COLORS[badgeType] || 'var(--accent)'}"><svg width="${width}" height="${size}" viewBox="0 0 24 24"${isGem ? ' preserveAspectRatio="none"' : ''} fill="currentColor">${isGem ? GEM_BADGE_SVG : SEAL_BADGE_SVG}</svg></span>`;
}
function verifiedBadgeHtml(profileType, profileKey, staticBadges, size){
  const dynamic = (dynamicBadges[profileType] && dynamicBadges[profileType][profileKey]) || [];
  const badges = dynamic.length ? dynamic : (staticBadges || []);
  return badges.map(b => badgeIconHtml(b, size)).join('');
}
function escapeHtmlGlobal(s){
  const d = document.createElement('div');
  d.textContent = s === undefined || s === null ? '' : s;
  return d.innerHTML;
}
function escapeAttrGlobal(s){
  return escapeHtmlGlobal(s).replace(/"/g, '&quot;').replace(/'/g, '&#39;');
}

